"#/components/responses/Error\"\n          }\n        }\n      }\n    },\n    \"/api/monitoring/proposals/{id}/resolve\": {\n      \"post\": {\n        \"summary\": \"Resolve an open claim-update proposal with an attributable note\",\n        \"security\": [\n          {\n            \"session\": []\n          }\n        ],\n        \"parameters\": [\n          {\n            \"name\": \"id\",\n            \"in\": \"path\",\n            \"required\": true,\n            \"schema\": {\n              \"type\": \"string\"\n            }\n          }\n        ],\n        \"responses\": {\n          \"200\": {\n            \"description\": \"Resolved\"\n          },\n          \"409\": {\n            \"$ref\": \"#/components/responses/Error\"\n          }\n        }\n      }\n    },\n    \"/api/protocols/snapshots\": {\n      \"post\": {\n        \"summary\": \"Register an exact OSF or ClinicalTrials.gov protocol snapshot and open neutral proposals\",\n        \"description\": \"Editor-only, same-origin, rate- and body-limited ingestion. The same target/source version with different content is rejected; an exact retry is idempotent. No registry network request occurs in this endpoint.\\n\",\n        \"security\": [\n          {\n            \"session\": []\n          }\n        ],\n        \"requestBody\": {\n          \"required\": true,\n          \"content\": {\n            \"application/json\": {\n              \"schema\": {\n                \"$ref\": \"#/components/schemas/ProtocolSnapshotRequest\"\n              }\n            }\n          }\n        },\n        \"responses\": {\n          \"200\": {\n            \"description\": \"Immutable snapshot and deterministic proposal counts\"\n          },\n          \"400\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"403\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"409\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"413\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"429\": {\n            \"$ref\": \"#/components/responses/Error\"\n          }\n        }\n      }\n    },\n    \"/api/protocols/proposals/{id}/resolve\": {\n      \"post\": {\n        \"summary\": \"Resolve one neutral protocol reconciliation proposal with attribution\",\n        \"security\": [\n          {\n            \"session\": []\n          }\n        ],\n        \"parameters\": [\n          {\n            \"name\": \"id\",\n            \"in\": \"path\",\n            \"required\": true,\n            \"schema\": {\n              \"type\": \"string\"\n            }\n          }\n        ],\n        \"requestBody\": {\n          \"required\": true,\n          \"content\": {\n            \"application/json\": {\n              \"schema\": {\n                \"$ref\": \"#/components/schemas/ProtocolProposalResolution\"\n              }\n            }\n          }\n        },\n        \"responses\": {\n          \"200\": {\n            \"description\": \"Proposal resolved exactly once\"\n          },\n          \"403\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"409\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"413\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"429\": {\n            \"$ref\": \"#/components/responses/Error\"\n          }\n        }\n      }\n    },\n    \"/api/editorial/node-edge-proposals/{id}/decision\": {\n      \"post\": {\n        \"summary\": \"Confirm, reject, or supersede an attributable node-edge proposal\",\n        \"description\": \"Current editor/admin role, same-origin JSON, rate and body limits, and an expected revision are required. Only confirmation materializes an authoritative NodeEdge.\\n\",\n        \"security\": [\n          {\n            \"session\": []\n          }\n        ],\n        \"parameters\": [\n          {\n            \"name\": \"id\",\n            \"in\": \"path\",\n            \"required\": true,\n            \"schema\": {\n              \"type\": \"string\"\n            }\n          }\n        ],\n        \"requestBody\": {\n          \"required\": true,\n          \"content\": {\n            \"application/json\": {\n              \"schema\": {\n                \"$ref\": \"#/components/schemas/NodeEdgeDecision\"\n              }\n            }\n          }\n        },\n        \"responses\": {\n          \"200\": {\n            \"description\": \"CAS decision result; exact retries are idempotent\"\n          },\n          \"400\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"403\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"404\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"409\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"413\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"429\": {\n            \"$ref\": \"#/components/responses/Error\"\n          }\n        }\n      }\n    },\n    \"/api/editorial/node-identity-proposals/{id}/decision\": {\n      \"post\": {\n        \"summary\": \"Confirm or reject one deterministic same-claim proposal\",\n        \"description\": \"Requires a current editor/admin and optimistic revision. Confirmation publishes only an “also asserted in” identity; it never merges nodes or combines protocol-scoped TRUST data.\\n\",\n        \"security\": [\n          {\n            \"session\": []\n          }\n        ],\n        \"parameters\": [\n          {\n            \"name\": \"id\",\n            \"in\": \"path\",\n            \"required\": true,\n            \"schema\": {\n              \"type\": \"string\"\n            }\n          }\n        ],\n        \"requestBody\": {\n          \"required\": true,\n          \"content\": {\n            \"application/json\": {\n              \"schema\": {\n                \"$ref\": \"#/components/schemas/NodeIdentityDecision\"\n              }\n            }\n          }\n        },\n        \"responses\": {\n          \"200\": {\n            \"description\": \"CAS decision result; exact retries are idempotent\"\n          },\n          \"400\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"403\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"404\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"409\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"413\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"429\": {\n            \"$ref\": \"#/components/responses/Error\"\n          }\n        }\n      }\n    },\n    \"/api/editorial/syntheses/generate\": {\n      \"post\": {\n        \"summary\": \"Generate one private immutable grounded-synthesis draft\",\n        \"description\": \"Claims a caller request key before provider execution, binds it to one canonical selector, snapshots the exact bounded evidence packet and successful AgentRun, and creates no public review.\\n\",\n        \"security\": [\n          {\n            \"session\": []\n          }\n        ],\n        \"requestBody\": {\n          \"required\": true,\n          \"content\": {\n            \"application/json\": {\n              \"schema\": {\n                \"$ref\": \"#/components/schemas/SynthesisGenerationRequest\"\n              }\n            }\n          }\n        },\n        \"responses\": {\n          \"200\": {\n            \"description\": \"Private editorial synthesis draft\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/EditorialSynthesisDraft\"\n                }\n              }\n            }\n          },\n          \"400\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"403\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"409\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"413\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"429\": {\n            \"$ref\": \"#/components/responses/Error\"\n          }\n        }\n      }\n    },\n    \"/api/editorial/syntheses/{id}/decision\": {\n      \"post\": {\n        \"summary\": \"Accept, reject, or request regeneration of a private synthesis draft\",\n        \"description\": \"Rechecks the editor role, binds the idempotency key to the canonical decision body, and uses serializable CAS. Only acceptance materializes and advances the public synthesis head.\\n\",\n        \"security\": [\n          {\n            \"session\": []\n          }\n        ],\n        \"parameters\": [\n          {\n            \"name\": \"id\",\n            \"in\": \"path\",\n            \"required\": true,\n            \"schema\": {\n              \"type\": \"string\"\n            }\n          }\n        ],\n        \"requestBody\": {\n          \"required\": true,\n          \"content\": {\n            \"application/json\": {\n              \"schema\": {\n                \"$ref\": \"#/components/schemas/SynthesisDecision\"\n              }\n            }\n          }\n        },\n        \"responses\": {\n          \"200\": {\n            \"description\": \"Idempotent editorial decision result\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/SynthesisDecisionResult\"\n                }\n              }\n            }\n          },\n          \"400\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"403\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"404\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"409\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"413\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"429\": {\n            \"$ref\": \"#/components/responses/Error\"\n          }\n        }\n      }\n    },\n    \"/api/editorial/syntheses/staleness/scan\": {\n      \"post\": {\n        \"summary\": \"Evaluate accepted synthesis heads and create private regeneration proposals\",\n        \"description\": \"Bounded deterministic scan of each exact accepted selector and packet. It records immutable evaluations and deduplicated private proposals but never calls a provider, creates a draft, or publishes a review.\\n\",\n        \"security\": [\n          {\n            \"session\": []\n          }\n        ],\n        \"requestBody\": {\n          \"required\": true,\n          \"content\": {\n            \"application/json\": {\n              \"schema\": {\n                \"type\": \"object\",\n                \"additionalProperties\": false,\n                \"properties\": {\n                  \"cursor\": {\n                    \"type\": \"string\",\n                    \"minLength\": 1,\n                    \"maxLength\": 200\n                  },\n                  \"limit\": {\n                    \"type\": \"integer\",\n                    \"minimum\": 1,\n                    \"maximum\": 100,\n                    \"default\": 100\n                  }\n                }\n              }\n            }\n          }\n        },\n        \"responses\": {\n          \"200\": {\n            \"description\": \"Bounded allowlisted scan results\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/SynthesisStalenessScanResult\"\n                }\n              }\n            }\n          },\n          \"400\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"403\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"409\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"413\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"429\": {\n            \"$ref\": \"#/components/responses/Error\"\n          }\n        }\n      }\n    },\n    \"/api/editorial/syntheses/staleness/{id}/decision\": {\n      \"post\": {\n        \"summary\": \"Request private regeneration or dismiss one current proposal\",\n        \"description\": \"Rechecks the accepted head and editor role and applies idempotent revision CAS. No generation occurs.\",\n        \"security\": [\n          {\n            \"session\": []\n          }\n        ],\n        \"parameters\": [\n          {\n            \"name\": \"id\",\n            \"in\": \"path\",\n            \"required\": true,\n            \"schema\": {\n              \"type\": \"string\"\n            }\n          }\n        ],\n        \"requestBody\": {\n          \"required\": true,\n          \"content\": {\n            \"application/json\": {\n              \"schema\": {\n                \"$ref\": \"#/components/schemas/SynthesisRegenerationProposalDecision\"\n              }\n            }\n          }\n        },\n        \"responses\": {\n          \"200\": {\n            \"description\": \"Idempotent proposal decision\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/SynthesisRegenerationProposalDecisionResult\"\n                }\n              }\n            }\n          },\n          \"400\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"403\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"404\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"409\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"413\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"429\": {\n            \"$ref\": \"#/components/responses/Error\"\n          }\n        }\n      }\n    },\n    \"/api/syntheses/{slug}\": {\n      \"get\": {\n        \"summary\": \"Read the current editor-accepted AI synthesis from its authoritative head\",\n        \"description\": \"Returns an allowlisted public DTO only after revalidating the linked immutable draft, AgentRun, canonical hashes, citations, attribution, rights, and predecessor lineage.\\n\",\n        \"parameters\": [\n          {\n            \"name\": \"slug\",\n            \"in\": \"path\",\n            \"required\": true,\n            \"schema\": {\n              \"type\": \"string\"\n            }\n          }\n        ],\n        \"responses\": {\n          \"200\": {\n            \"description\": \"Current accepted synthesis without private packet or run fields\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/PublicSynthesisReview\"\n                }\n              }\n            }\n          },\n          \"404\": {\n            \"$ref\": \"#/components/responses/Error\"\n          }\n        }\n      }\n    },\n    \"/api/nodes/{id}/edges\": {\n      \"get\": {\n        \"summary\": \"Minimal public confirmed-edge projection for one knowledge node\",\n        \"description\": \"Rejected, superseded, and unconfirmed proposals are excluded; contradictions project symmetrically.\",\n        \"parameters\": [\n          {\n            \"name\": \"id\",\n            \"in\": \"path\",\n            \"required\": true,\n            \"schema\": {\n              \"type\": \"string\"\n            }\n          }\n        ],\n        \"responses\": {\n          \"200\": {\n            \"description\": \"Bounded list of at most 200 editor-confirmed typed edges; never cached\"\n          }\n        }\n      }\n    },\n    \"/api/protocols/reviews/{versionId}\": {\n      \"get\": {\n        \"summary\": \"Public review-level protocol provenance and neutral reconciliation proposals\",\n        \"parameters\": [\n          {\n            \"name\": \"versionId\",\n            \"in\": \"path\",\n            \"required\": true,\n            \"schema\": {\n              \"type\": \"string\"\n            }\n          }\n        ],\n        \"responses\": {\n          \"200\": {\n            \"description\": \"Normalized snapshots, exact versions/timestamps/hashes, and proposal states\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/ProtocolDriftSummary\"\n                }\n              }\n            }\n          },\n          \"404\": {\n            \"$ref\": \"#/components/responses/Error\"\n          }\n        }\n      }\n    },\n    \"/api/synthesis/contradictions\": {\n      \"get\": {\n        \"summary\": \"Cross-review contradiction map with independence-aware classification\",\n        \"responses\": {\n          \"200\": {\n            \"description\": \"Contradictions between opposing claims that share an evidence family, each classified as a genuine contradiction or a scope difference, plus review/statement counts.\\n\"\n          }\n        }\n      }\n    },\n    \"/api/replications\": {\n      \"get\": {\n        \"summary\": \"List human-published replication briefs\",\n        \"description\": \"Returns only briefs tied to readable claims. The categorical evidence-gap metadata is deterministic editorial triage, not a truth score, outcome prediction, or person ranking.\\n\",\n        \"parameters\": [\n          {\n            \"name\": \"status\",\n            \"in\": \"query\",\n            \"schema\": {\n              \"type\": \"string\",\n              \"enum\": [\n                \"open\",\n                \"claimed\",\n                \"completed\",\n                \"withdrawn\"\n              ]\n            }\n          },\n          {\n            \"name\": \"effortBand\",\n            \"in\": \"query\",\n            \"schema\": {\n              \"type\": \"string\",\n              \"enum\": [\n                \"small\",\n                \"medium\",\n                \"large\",\n                \"consortium\"\n              ]\n            }\n          },\n          {\n            \"name\": \"page\",\n            \"in\": \"query\",\n            \"schema\": {\n              \"type\": \"integer\",\n              \"minimum\": 1,\n              \"maximum\": 10000,\n              \"default\": 1\n            }\n          },\n          {\n            \"name\": \"pageSize\",\n            \"in\": \"query\",\n            \"schema\": {\n              \"type\": \"integer\",\n              \"minimum\": 1,\n              \"maximum\": 50,\n              \"default\": 20\n            }\n          }\n        ],\n        \"responses\": {\n          \"200\": {\n            \"description\": \"Bounded page of public replication briefs\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/ReplicationMarketplacePage\"\n                }\n              }\n            }\n          },\n          \"400\": {\n            \"$ref\": \"#/components/responses/Error\"\n          }\n        }\n      },\n      \"post\": {\n        \"summary\": \"Register a private replication-brief draft\",\n        \"description\": \"Editor-only and idempotent. This operation never publishes automatically.\",\n        \"security\": [\n          {\n            \"session\": []\n          }\n        ],\n        \"requestBody\": {\n          \"required\": true,\n          \"content\": {\n            \"application/json\": {\n              \"schema\": {\n                \"$ref\": \"#/components/schemas/ReplicationBriefCreateRequest\"\n              }\n            }\n          }\n        },\n        \"responses\": {\n          \"200\": {\n            \"description\": \"Draft registered or idempotently replayed\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/ReplicationBriefMutationResult\"\n                }\n              }\n            }\n          },\n          \"400\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"403\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"409\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"413\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"429\": {\n            \"$ref\": \"#/components/responses/Error\"\n          }\n        }\n      }\n    },\n    \"/api/replications/{slug}\": {\n      \"get\": {\n        \"summary\": \"Get one public replication brief and its attributable lifecycle\",\n        \"parameters\": [\n          {\n            \"name\": \"slug\",\n            \"in\": \"path\",\n            \"required\": true,\n            \"schema\": {\n              \"type\": \"string\",\n              \"maxLength\": 100\n            }\n          }\n        ],\n        \"responses\": {\n          \"200\": {\n            \"description\": \"Published replication brief\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/ReplicationBrief\"\n                }\n              }\n            }\n          },\n          \"404\": {\n            \"$ref\": \"#/components/responses/Error\"\n          }\n        }\n      }\n    },\n    \"/api/replications/{slug}/transitions\": {\n      \"post\": {\n        \"summary\": \"Apply an authenticated replication-brief lifecycle transition\",\n        \"description\": \"Publishing and withdrawal require an editor. Claiming requires a signed-in user. Only the attributable claimant can record completion. Every transition is audited and CAS-guarded.\\n\",\n        \"security\": [\n          {\n            \"session\": []\n          }\n        ],\n        \"parameters\": [\n          {\n            \"name\": \"slug\",\n            \"in\": \"path\",\n            \"required\": true,\n            \"schema\": {\n              \"type\": \"string\",\n              \"maxLength\": 100\n            }\n          }\n        ],\n        \"requestBody\": {\n          \"required\": true,\n          \"content\": {\n            \"application/json\": {\n              \"schema\": {\n                \"$ref\": \"#/components/schemas/ReplicationBriefTransitionRequest\"\n              }\n            }\n          }\n        },\n        \"responses\": {\n          \"200\": {\n            \"description\": \"Transition committed\",\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/ReplicationBriefMutationResult\"\n                }\n              }\n            }\n          },\n          \"400\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"403\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"404\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"409\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"413\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"429\": {\n            \"$ref\": \"#/components/responses/Error\"\n          }\n        }\n      }\n    },\n    \"/api/federation/inbox\": {\n      \"get\": {\n        \"summary\": \"List accepted federation notification resource URLs as an LDN container\",\n        \"description\": \"Returns only editor-accepted inbound notifications with bounded cursor pagination.\",\n        \"parameters\": [\n          {\n            \"name\": \"cursor\",\n            \"in\": \"query\",\n            \"description\": \"Opaque cursor from the preceding Link rel=next URL.\",\n            \"schema\": {\n              \"type\": \"string\",\n              \"minLength\": 1,\n              \"maxLength\": 200\n            }\n          },\n          {\n            \"name\": \"limit\",\n            \"in\": \"query\",\n            \"description\": \"Maximum notification URLs to return.\",\n            \"schema\": {\n              \"type\": \"integer\",\n              \"minimum\": 1,\n              \"maximum\": 100,\n              \"default\": 50\n            }\n          }\n        ],\n        \"responses\": {\n          \"200\": {\n            \"description\": \"JSON-LD LDP container with accepted notification URLs\",\n            \"headers\": {\n              \"Link\": {\n                \"description\": \"Present when another page exists; carries the next cursor with rel=next.\",\n                \"schema\": {\n                  \"type\": \"string\"\n                }\n              }\n            }\n          },\n          \"400\": {\n            \"$ref\": \"#/components/responses/Error\"\n          }\n        }\n      },\n      \"options\": {\n        \"summary\": \"Advertise accepted LDN notification media types\",\n        \"responses\": {\n          \"204\": {\n            \"description\": \"Allow and Accept-Post headers\"\n          }\n        }\n      },\n      \"post\": {\n        \"summary\": \"Receive a COAR Notify Request Review or Announce Review activity\",\n        \"description\": \"Public rate-limited JSON-LD inbox. External URLs are preserved as identifiers and are never dereferenced. New messages remain pending until an editor resolves them.\\n\",\n        \"requestBody\": {\n          \"required\": true,\n          \"content\": {\n            \"application/ld+json\": {\n              \"schema\": {\n                \"type\": \"object\"\n              }\n            },\n            \"application/json\": {\n              \"schema\": {\n                \"type\": \"object\"\n              }\n            }\n          }\n        },\n        \"responses\": {\n          \"200\": {\n            \"description\": \"Idempotent receipt of the same activity and payload\"\n          },\n          \"202\": {\n            \"description\": \"Immutable notification persisted privately for editorial triage\"\n          },\n          \"400\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"409\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"413\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"429\": {\n            \"$ref\": \"#/components/responses/Error\"\n          }\n        }\n      }\n    },\n    \"/api/federation/notifications/{id}\": {\n      \"get\": {\n        \"summary\": \"Read an editor-accepted immutable inbound federation notification as JSON-LD\",\n        \"description\": \"Pending, rejected, and unknown notification resources all return 404.\",\n        \"parameters\": [\n          {\n            \"name\": \"id\",\n            \"in\": \"path\",\n            \"required\": true,\n            \"schema\": {\n              \"type\": \"string\"\n            }\n          }\n        ],\n        \"responses\": {\n          \"200\": {\n            \"description\": \"Original COAR Notify JSON-LD payload\"\n          },\n          \"404\": {\n            \"$ref\": \"#/components/responses/Error\"\n          }\n        }\n      }\n    },\n    \"/api/editorial/federation\": {\n      \"get\": {\n        \"summary\": \"List inbound COAR Notify activities for editorial triage\",\n        \"security\": [\n          {\n            \"session\": []\n          }\n        ],\n        \"responses\": {\n          \"200\": {\n            \"description\": \"Federation queue\"\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"403\": {\n            \"$ref\": \"#/components/responses/Error\"\n          }\n        }\n      }\n    },\n    \"/api/editorial/federation/{id}/resolve\": {\n      \"post\": {\n        \"summary\": \"Accept or reject a pending federated review request\",\n        \"security\": [\n          {\n            \"session\": []\n          }\n        ],\n        \"parameters\": [\n          {\n            \"name\": \"id\",\n            \"in\": \"path\",\n            \"required\": true,\n            \"schema\": {\n              \"type\": \"string\"\n            }\n          }\n        ],\n        \"requestBody\": {\n          \"required\": true,\n          \"content\": {\n            \"application/json\": {\n              \"schema\": {\n                \"type\": \"object\",\n                \"required\": [\n                  \"decision\",\n                  \"note\"\n                ],\n                \"properties\": {\n                  \"decision\": {\n                    \"type\": \"string\",\n                    \"enum\": [\n                      \"accepted\",\n                      \"rejected\"\n                    ]\n                  },\n                  \"note\": {\n                    \"type\": \"string\",\n                    \"minLength\": 10,\n                    \"maxLength\": 4000\n                  }\n                }\n              }\n            }\n          }\n        },\n        \"responses\": {\n          \"200\": {\n            \"description\": \"Attributable editorial resolution\"\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"403\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"404\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"409\": {\n            \"$ref\": \"#/components/responses/Error\"\n          }\n        }\n      }\n    },\n    \"/api/reviews/{slug}/versions/{versionId}/federation/announce\": {\n      \"post\": {\n        \"summary\": \"Prepare an Announce Review reply to an accepted Request Review\",\n        \"description\": \"Persists and audits JSON-LD without delivering it or making external requests.\",\n        \"security\": [\n          {\n            \"session\": []\n          }\n        ],\n        \"parameters\": [\n          {\n            \"name\": \"slug\",\n            \"in\": \"path\",\n            \"required\": true,\n            \"schema\": {\n              \"type\": \"string\"\n            }\n          },\n          {\n            \"name\": \"versionId\",\n            \"in\": \"path\",\n            \"required\": true,\n            \"schema\": {\n              \"type\": \"string\"\n            }\n          }\n        ],\n        \"requestBody\": {\n          \"required\": true,\n          \"content\": {\n            \"application/json\": {\n              \"schema\": {\n                \"type\": \"object\",\n                \"additionalProperties\": false,\n                \"required\": [\n                  \"inReplyTo\"\n                ],\n                \"properties\": {\n                  \"inReplyTo\": {\n                    \"type\": \"string\",\n                    \"format\": \"uri\",\n                    \"maxLength\": 2048\n                  }\n                }\n              }\n            }\n          }\n        },\n        \"responses\": {\n          \"200\": {\n            \"description\": \"COAR Notify 1.0.1 Announce Review JSON-LD\"\n          },\n          \"400\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"403\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"404\": {\n            \"$ref\": \"#/components/responses/Error\"\n          },\n          \"409\": {\n            \"$ref\": \"#/components/responses/Error\"\n          }\n        }\n      }\n    }\n  }\n}\n";
